gUb(){return"down"},
gUc(){return"left"},
gUd(){return"right"},
Uj(a){var s=null
return A.bO(a,s,this.a,s,"1 pair",""+a+" pairs",s,s)},
Ug(a,b,c){return"Slide "+a+": it merges "+b+" of tiles (+"+c+" points). It's a heuristic, not a proof: it looks a few moves ahead."},
Ui(a,b){return"Slide "+a+": nothing to merge for now, but it keeps the board best in order around the biggest tile ("+b+" free cells). It's a heuristic, not a proof: it looks a few moves ahead."},
Uh(a){return"Only one move is possible: slide "+a+"."},
gHl(){return"even"},
gHm(){return"odd"},
aij(a,b,c){return"Look at the parity: "+a+". The result is "+b+", so "+c+" doesn't fit. I rule it out."},
aii(a,b,c,d){return"Look only at the units digit: "+a+". The result therefore ends in "+b+", and "+c+" ends in "+d+". I rule it out."},
aih(a,b){return"Check by going back: "+a+". That doesn't give back the right number, so "+b+" doesn't fit. I rule it out."},
aig(a){return"Only "+a+" is left: it is the result."},
ads(a){return"I take "+a+" away: it isn't the right number of cubes."},
adr(a){return"Only "+a+" is left: it is the right number of cubes."},
